/** Les trois résolutions de la bande, pour un nombre de tampons. */
export function bandesFidelite(tampons: number): Record<string, Buffer> {
  const n = Math.max(0, Math.min(10, Math.round(tampons)));
  const out: Record<string, Buffer> = {};
  for (const [nom, b64] of Object.entries(BANDES[n])) {
    out[nom] = Buffer.from(b64, "base64");
  }
  return out;
}

/** Compatibilité : la version @2x seule. */
export function bandeFidelite(tampons: number): Buffer {
  return bandesFidelite(tampons)["strip@2x.png"];
}
